        "personality": "10代後半で留学生として遣唐使と共に唐に渡った阿部仲麻呂は、20代で科挙に合格し、要職を得て<ruby>玄宗<rt>げんそう</rt></ruby>皇帝に仕えました。優れた才能のため唐での職を離れることを許されず、50歳を過ぎてやっと帰国の途につきましたが、船が暴風雨に遭いベトナムに漂着しました。その後、長安に戻り73歳で亡くなりました。",
