// ----------------------------------------------
// 歌人を選ぶとURLを遷移させる
// ----------------------------------------------

// 歌人が変更されたときにURLを更新する
$("#jsonSelector").on("change", function () {
    const selectedNumber = parseInt($(this).val());
    if (!isNaN(selectedNumber)) {
        // 英語ページ（_en.html）の場合はサフィックスを保持する
        const suffix = window.location.href.match(/_[a-z]+\.html/) ? "_en" : "";
        const newUrl = baseURL + selectedNumber + suffix + ".html";
        window.location.href = newUrl;
    }
});



function getPoemNumberFromUrl() {
    const currentUrl = window.location.href;

    // #が含まれている場合
    if (currentUrl.includes('#')) {
        const regexPattern = /\/(\d+)(?:_[a-z]+)?\.html(?=#)/;
        const matches = currentUrl.match(regexPattern);
        if (matches && matches.length > 1) {
            return parseInt(matches[1]);
        }
    }
    // #が含まれていない場合
    else {
        const regexPattern = /\/(\d+)(?:_[a-z]+)?\.html$/;
        const matches = currentUrl.match(regexPattern);
        if (matches && matches.length > 1) {
            return parseInt(matches[1]);
        }
    }

    return null;
}


// URLから詩の番号を取得し、jsonSelectorで選択状態にする
$(document).ready(function () {
    const selectedNumber = getPoemNumberFromUrl();
    if (!isNaN(selectedNumber)) {
        $("#jsonSelector").val(selectedNumber);
    }
});


// ----------------------------------------------
// スイッチで札を裏返すトグル
// ----------------------------------------------
function saveToggleState() {
    var toggle2 = document.getElementById("toggle2");
    if (!toggle2) return;
    var toggleState = toggle2.checked;
    localStorage.setItem("toggleState", toggleState);
}

// 保存された #toggle2 の状態を適用する関数
function applyToggleState() {
    var toggle2 = document.getElementById("toggle2");
    if (!toggle2) return;
    var toggleState = localStorage.getItem("toggleState") === "true";
    var cardItems = document.querySelectorAll(".card-item");

    toggle2.checked = toggleState;

    // トグルの状態に応じてボタンの表示を更新
    updateButtonVisibility(toggleState);

    cardItems.forEach(function (item) {
        item.classList.toggle("active", toggleState);
    });
}

// ボタンの表示/非表示を切り替える関数
function updateButtonVisibility(isChecked) {
    const playPauseBtn = document.getElementById("play-pause-btn");
    const japanese = document.getElementById("japanese");
    const audioCredit = document.getElementById("audio-credit");
    const playPauseBtnEn = document.getElementById("play-pause-btn-en");
    const english = document.getElementById("english");
    const audioCreditEn = document.getElementById("audio-credit-en");


    if (isChecked) {
        // playPauseBtn.style.display = "none";
        // playPauseBtnEn.style.display = "block";
        // japanese.style.display="none";
        // english.style.display="block";
        // audioCredit.style.display="none";
        // audioCreditEn.style.display="block";
        playPauseBtn.style.display = "block";
        playPauseBtnEn.style.display = "none";
        english.style.display = "none";
        japanese.style.display = "block";
        audioCreditEn.style.display = "none";
        audioCredit.style.display = "block";
    } else {
        playPauseBtn.style.display = "block";
        playPauseBtnEn.style.display = "none";
        english.style.display = "none";
        japanese.style.display = "block";
        audioCreditEn.style.display = "none";
        audioCredit.style.display = "block";

    }
}

// ページ遷移前に #toggle2 の状態を保存する
window.addEventListener("beforeunload", saveToggleState);

// ページ遷移後に保存された #toggle2 の状態を適用する
window.addEventListener("load", function () {
    applyToggleState();

    // チェックボックスの変更によるイベントリスナー
    var toggle2 = document.getElementById("toggle2");
    if (!toggle2) return;
    var cardItems = document.querySelectorAll(".card-item");

    toggle2.addEventListener("change", function (event) {
        var isChecked = event.target.checked;

        // アニメーション完了を待ってからクラスをトグル
        cardItems.forEach(function (item) {
            // 既存のactiveクラスがあれば、アニメーション完了後に処理
            if (item.classList.contains('active')) {
                setTimeout(() => {
                    item.classList.remove('active');
                }, 10);
            } else {
                item.classList.add('active');
            }
        });
    });
});

// ----------------------------------------------
// 次へ・戻るボタン
// ----------------------------------------------
$(function () {
    // 次へボタンのクリックイベントハンドラ
    $("#next, #next2.bottom").on("click", function (event) {
        const selectMenu = document.getElementById("jsonSelector");
        let currentOptionIndex = selectMenu.selectedIndex;

        // 次の選択肢のインデックスを計算
        let nextOptionIndex = currentOptionIndex + 1;
        if (nextOptionIndex >= selectMenu.options.length) {
            nextOptionIndex = 0;
        }


        // 現在の選択肢が"all"の場合、次の選択肢に進む（allをスキップ）
        while (selectMenu.options[nextOptionIndex].value === "all") {
            nextOptionIndex++;
            if (nextOptionIndex >= selectMenu.options.length) {
                nextOptionIndex = 0;
            }
        }

        // 次の選択肢に設定
        selectMenu.selectedIndex = nextOptionIndex;
        const changeEvent = new Event("change");
        selectMenu.dispatchEvent(changeEvent);
    });

    // 戻るボタンのクリックイベントハンドラ
    $("#back, #back2.bottom").on("click", function (event) {
        const selectMenu = document.getElementById("jsonSelector");
        let currentOptionIndex = selectMenu.selectedIndex;

        // 前の選択肢のインデックスを計算
        let previousOptionIndex = currentOptionIndex - 1;
        if (previousOptionIndex < 0) {
            previousOptionIndex = selectMenu.options.length - 1;
        }

        // 現在の選択肢が"all"の場合、前の選択肢に戻る（allをスキップ）
        while (selectMenu.options[previousOptionIndex].value === "all") {
            previousOptionIndex--;
            if (previousOptionIndex < 0) {
                previousOptionIndex = selectMenu.options.length - 1;
            }
        }

        // 前の選択肢に設定
        selectMenu.selectedIndex = previousOptionIndex;
        const changeEvent = new Event("change");
        selectMenu.dispatchEvent(changeEvent);
    });

});



// ----------------------------------------------
// トップに戻る
// ----------------------------------------------
$(function () {
    var pagetop = $("#page-top");
    pagetop.hide();
    $(window).scroll(function () {
        var scrollTop = $(this).scrollTop();
        // フッター（お問い合わせフォーム等のリンク）に重なるのを防ぐため、
        // ページ最下部付近では非表示にする
        var nearBottom = scrollTop + $(this).height() > $(document).height() - 150;
        if (scrollTop > 100 && !nearBottom) {
            pagetop.fadeIn();
        } else {
            pagetop.fadeOut();
        }
    });
    pagetop.click(function () {
        $("html,body").animate({ scrollTop: 0 }, 800);
        return false;
    });
});

